, "confidence": "", "notes": "Pendiente: la revisión manual de perfiles se detuvo; verificar con la corrida de Apify (perfil, no posts)."}]'::jsonb) as x(slug text,instagram_handle text,handle_status text,city text,verification_source text,notes text)),
matched as (select lower(i.instagram_handle) as username,i.*,v.id as matched_id,v.disposition as venue_disposition from input i left join public.venues v on v.slug=i.slug where i.instagram_handle ~ '^[a-zA-Z0-9._]{1,30}$'),
grouped as (select username,
 case when count(distinct matched_id) filter(where handle_status='VERIFIED' and venue_disposition='published')=1 then 'active'
 when bool_and(handle_status in ('INACTIVE','NOT_FOUND')) then 'rejected' else 'candidate' end as status,
 case when count(distinct matched_id) filter(where handle_status='VERIFIED' and venue_disposition='published')=1 then min(matched_id) filter(where handle_status='VERIFIED' and venue_disposition='published') else null end as venue_id,
 case when count(distinct city)=1 then min(city) else null end as city,
 string_agg(distinct slug||': '||handle_status||' | '||coalesce(verification_source,'')||' | '||coalesce(notes,''), E'\n') as note
 from matched group by username)
insert into public.instagram_accounts(username,kind,status,venue_id,city,origin,note)
select username,'venue',status,venue_id,city,'venue_master_2026-10-16',note from grouped
on conflict(username) do nothing;
